package ama.transcript;

import ama.access.MeetingAccess;
import ama.config.*;
import ama.contract.ConfigArchiveContracts.Ref;
import ama.contract.IdentityContracts.Actor;
import ama.contract.MinutesContracts.*;
import ama.minutes.*;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.util.function.Supplier;
import static ama.contract.MinutesContracts.*;
import static ama.contract.MinutesContracts.FailureCode.*;

/** Owner-private projections. Metadata does not assert archived graph validity; details use S/A/F. */
public final class JdbcMinutesQueries {
 private final JdbcTranscriptAuthority authority;private final JdbcTemplate j;private final JdbcMinutesFactsReader reader;private final Supplier<ConfigArchiveSource.Snapshot> archives;private final Ref prompt,model;
 public JdbcMinutesQueries(JdbcTranscriptAuthority authority,Supplier<ConfigArchiveSource.Snapshot> archives,String pin,Ref prompt,Ref model,TranscriptAcquisitionBudget limits){this.authority=authority;this.archives=archives;this.prompt=prompt;this.model=model;j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);reader=new JdbcMinutesFactsReader(authority,archives,pin,limits);}
 public Map<String,Object> templates(Actor actor,String meeting,int limit,String after){
  page(limit);if(after!=null)uuid(after);MinutesCatalogAdmission.Selection selection=null;RuntimeException error=null;try{selection=MinutesCatalogAdmission.capture(archives.get(),prompt,model,authority.readBudget());}catch(RuntimeException unavailable){error=unavailable;}
  if(error!=null){authorize(actor,meeting);throw error;}var snapshot=reader.readOwner(actor,meeting,"INITIAL_SETTINGS",selection.defaultTemplateRevisionId());var revision=JdbcMinutesFactsReader.one(snapshot.graph(),Table.TEMPLATE_REVISION,selection.defaultTemplateRevisionId());var parents=snapshot.graph().auxiliary().getOrDefault("minutes_template",List.of());require(parents.size()==1,PROVENANCE_UNAVAILABLE);var parent=parents.getFirst();require(revision.nullableString("owner_id")==null&&parent.get("owner_id")==null&&revision.string("template_id").equals(parent.get("id"))&&revision.string("id").equals(parent.get("current_revision_id"))&&revision.number("revision")==1&&revision.number("theme_count")==7&&ControlledMinutesTemplateInstaller.NAME.equals(revision.string("name"))&&ControlledMinutesTemplateInstaller.THEMES.equals(revision.string("themes")),PROFILE_UNAVAILABLE);
  var item=Map.<String,Object>of("templateId",revision.string("template_id"),"revisionId",revision.string("id"),"name",revision.string("name"),"themes",Arrays.stream(Category.values()).map(Enum::name).toList(),"themeCount",7,"selectable",true,"default",true);boolean include=after==null||revision.string("template_id").compareTo(after)>0;return map("items",include?List.of(item):List.of(),"nextCursor",null,"observation",observation(snapshot));
 }
 public Map<String,Object> current(Actor actor,String meeting){var snapshot=reader.readOwner(actor,meeting,"CURRENT_GENERATION",null);var root=snapshot.observation();var tasks=taskRows(actor,meeting);var active=tasks.stream().filter(t->Set.of("READY","RUNNING","RECONCILING").contains(t.get("state"))).map(t->t.get("id")).toList();return map("saved",map("transcriptConfirmationId",root.get("transcript_confirmation_id"),"templateRevisionId",root.get("template_revision_id"),"exclusionRevisionId",root.get("exclusion_revision_id"),"elementSetId",root.get("element_set_id")),"scope","FULL","materials","EMPTY","activeTaskIds",active,"eligible",false,"reasons",List.of("TASK10_NOT_INSTALLED","TASK11_NOT_INSTALLED"),"observation",observation(snapshot));}
 public Map<String,Object> input(Actor actor,String meeting,String input){uuid(input);var snapshot=reader.readOwner(actor,meeting,"STORED_INPUT",input);var selected=JdbcMinutesFactsReader.one(snapshot.graph(),Table.GENERATION_INPUT,input);return map("input",project(selected),"manifestJson",snapshot.generationManifestJson(input),"profiles",snapshot.roots().stream().map(r->Map.of("artifactType",r.artifactType().name(),"version",r.version(),"sha256",r.sha256())).toList(),"provenanceVerified",true,"currentReadiness",map("eligible",false,"reasons",List.of("TASK10_NOT_INSTALLED","TASK11_NOT_INSTALLED")),"observation",observation(snapshot));}
 public Map<String,Object> task(Actor actor,String meeting,String task){uuid(task);var rows=taskRows(actor,meeting).stream().filter(t->task.equals(t.get("id"))).toList();require(rows.size()==1,PROVENANCE_UNAVAILABLE);var row=rows.getFirst();var snapshot=reader.readOwner(actor,meeting,"STORED_INPUT",(String)row.get("input_id"));var actual=snapshot.graph().auxiliary().getOrDefault("durable_task",List.of()).stream().filter(t->task.equals(t.get("id"))).toList();require(actual.size()==1,PROVENANCE_UNAVAILABLE);var candidates=snapshot.graph().auxiliary().getOrDefault("generation_candidate",List.of()).stream().filter(c->task.equals(c.get("task_id"))).toList();require(candidates.size()<=1,PROVENANCE_UNAVAILABLE);var executions=snapshot.graph().auxiliary().getOrDefault("external_execution",List.of()).stream().filter(e->task.equals(e.get("task_id"))).toList();require(executions.size()<=1,PROVENANCE_UNAVAILABLE);var attempts=snapshot.graph().auxiliary().getOrDefault("task_attempt",List.of()).stream().filter(a->task.equals(a.get("task_id"))).map(a->map("attemptToken",token(a.get("attempt")),"outcome",a.get("outcome"),"errorCode",a.get("error_code"),"startedAt",a.get("started_at"),"endedAt",a.get("ended_at"))).toList();return map("task",taskProjection(actual.getFirst()),"attempts",attempts,"remoteOutcome",executions.isEmpty()?"NOT_MARKED":executions.getFirst().get("state"),"localOutcome",actual.getFirst().get("state"),"candidateId",candidates.isEmpty()?null:candidates.getFirst().get("id"),"allowedActions",List.of("INSPECT"),"observation",observation(snapshot));}
 public Map<String,Object> tasks(Actor actor,String meeting,int limit,String cursor){page(limit);var all=taskRows(actor,meeting);int start=0;if(cursor!=null){uuid(cursor);while(start<all.size()&&!cursor.equals(all.get(start).get("id")))start++;if(start==all.size())throw fail(INVALID_ARGUMENT);start++;}int end=Math.min(all.size(),start+limit);return map("items",all.subList(start,end).stream().map(this::taskProjection).toList(),"nextCursor",end<all.size()?all.get(end-1).get("id"):null,"metadataOnly",true);}
 public Map<String,Object> candidates(Actor actor,String meeting,int limit,String state,String cursor){page(limit);require(Set.of("PENDING","ADOPTED","REJECTED","STALE","ALL").contains(state),INVALID_ARGUMENT);if(cursor!=null)uuid(cursor);return authority.transactionRunner().required(()->{var gate=authority.fileRegistry().lock(actor,meeting,MeetingAccess.Action.EDIT);var states=state.equals("ALL")?List.of("PENDING","ADOPTED","REJECTED","STALE"):List.of(state);var rows=new ArrayList<Map<String,Object>>();for(String selected:states)rows.addAll(j.queryForList("SELECT id,input_id,task_id,minutes_revision_id,element_set_id,base_revision,input_fingerprint,state,created_at,decided_at FROM generation_candidate FORCE INDEX (candidate_pending) WHERE meeting_id=? AND state=? ORDER BY created_at,id LIMIT 257",meeting,selected));require(rows.size()<=256,BUDGET_EXCEEDED);rows.sort(Comparator.comparing((Map<String,Object> v)->v.get("created_at").toString()).thenComparing(v->(String)v.get("id")));int start=0;if(cursor!=null){while(start<rows.size()&&!cursor.equals(rows.get(start).get("id")))start++;require(start<rows.size(),INVALID_ARGUMENT);start++;}int end=Math.min(rows.size(),start+limit);return map("items",rows.subList(start,end).stream().map(JdbcMinutesQueries::candidateProjection).toList(),"nextCursor",end<rows.size()?rows.get(end-1).get("id"):null,"metadataOnly",true);});}
 public Map<String,Object> candidate(Actor actor,String meeting,String candidate){uuid(candidate);var snapshot=reader.readOwner(actor,meeting,"CANDIDATE",candidate);var selected=snapshot.graph().auxiliary().getOrDefault("generation_candidate",List.of()).stream().filter(c->candidate.equals(c.get("id"))).toList();require(selected.size()==1,PROVENANCE_UNAVAILABLE);var included=Set.of(Table.MINUTES_REVISION,Table.ELEMENT_SET,Table.MINUTES_ELEMENT,Table.ACTION_ITEM,Table.ACTION_SUGGESTION,Table.SENSITIVE_DETECTION,Table.BACKGROUND_NOTE,Table.SOURCE_LOCATOR,Table.SENSITIVE_DETECTION_SOURCE,Table.BACKGROUND_NOTE_SOURCE,Table.EVIDENCE_LINK);var tables=new TreeMap<String,Object>();for(var table:included)tables.put(table.sqlName(),snapshot.facts().rows().stream().filter(row->row.table()==table).map(JdbcMinutesQueries::project).toList());return map("candidate",candidateProjection(selected.getFirst()),"graph",tables,"provenanceVerified",true,"eligibility",map("canAdopt",false,"reasons",List.of("TASK10_NOT_INSTALLED","TASK11_NOT_INSTALLED")),"observation",observation(snapshot));}
 private List<Map<String,Object>> taskRows(Actor actor,String meeting){uuid(meeting);return authority.transactionRunner().required(()->{authority.fileRegistry().lock(actor,meeting,MeetingAccess.Action.EDIT);var all=j.queryForList("SELECT id,task_type,pool,subject_kind,subject_id,producer_key,input_kind,input_id,input_fingerprint,business_version,cancel_epoch,priority,max_attempts,state,last_error,output_kind,output_id,attempt,created_at FROM durable_task FORCE INDEX (task_subject_history) WHERE subject_kind='MEETING' AND subject_id=? ORDER BY created_at,id LIMIT 257",meeting);require(all.size()<=256,BUDGET_EXCEEDED);var selected=new ArrayList<Map<String,Object>>();for(var row:all)if("MINUTES_GENERATE_V1".equals(row.get("task_type"))){var spec=TranscriptReadGraph.spec(row);MinutesTaskDomainPolicy.shape(spec);var inputs=j.queryForList("SELECT id FROM generation_input WHERE id=? AND meeting_id=? AND base_revision=? AND input_fingerprint=? AND scope='FULL' AND target_element_id IS NULL AND material_snapshot_id IS NULL",spec.input().id(),meeting,spec.businessVersion(),spec.inputFingerprint());require(inputs.size()==1,PROVENANCE_UNAVAILABLE);selected.add(row);}return List.copyOf(selected);});}
 private Map<String,Object> taskProjection(Map<String,Object> row){return map("taskId",row.get("id"),"inputId",row.get("input_id"),"inputFingerprint",row.get("input_fingerprint"),"businessVersionToken",token(row.get("business_version")),"cancelEpochToken",token(row.get("cancel_epoch")),"state",row.get("state"),"errorCode",row.get("last_error"),"outputKind",row.get("output_kind"),"outputId",row.get("output_id"),"attemptToken",token(row.get("attempt")));}
 private static Map<String,Object> candidateProjection(Map<String,Object> row){return map("candidateId",row.get("id"),"inputId",row.get("input_id"),"taskId",row.get("task_id"),"minutesRevisionId",row.get("minutes_revision_id"),"elementSetId",row.get("element_set_id"),"baseRevisionToken",token(row.get("base_revision")),"inputFingerprint",row.get("input_fingerprint"),"state",row.get("state"),"createdAt",token(row.get("created_at")),"decidedAt",token(row.get("decided_at")));}
 private void authorize(Actor actor,String meeting){authority.transactionRunner().required(()->{authority.fileRegistry().lock(actor,meeting,MeetingAccess.Action.EDIT);return null;});}
 private static Map<String,Object> observation(JdbcMinutesFactsReader.Snapshot snapshot){return JdbcMinutesSettingsReceipts.observation(snapshot.observation());}
 private static String token(Object value){return value==null?null:value.toString();}
 private static Map<String,Object> project(FullRow row){var out=new LinkedHashMap<String,Object>();for(int n=0;n<row.cells().size();n++){var column=row.table().columns().get(n);var cell=row.cells().get(n);out.put(column.kind()==CellKind.UINT?column.name()+"Token":column.name(),cell instanceof NullCell?null:cell instanceof UIntCell v?Long.toString(v.value()):((TextCell)cell).value());}return Collections.unmodifiableMap(out);}
 private static void page(int limit){require(limit>=1&&limit<=50,INVALID_ARGUMENT);}
 private static Map<String,Object> map(Object... pairs){var values=new LinkedHashMap<String,Object>();for(int n=0;n<pairs.length;n+=2)values.put((String)pairs[n],pairs[n+1]);return Collections.unmodifiableMap(values);}
}
